extern char **environ;
static libusb_context *context;
static pthread_once_t once=PTHREAD_ONCE_INIT;
static int init_error;
static void setup(void){init_error=libusb_init(&context);}
static void key(libusb_device *d,char *s,int parent){uint8_t ports[8];int n=libusb_get_port_numbers(d,ports,8);snprintf(s,64,"%u:",libusb_get_bus_number(d));if(n<0)return;for(int i=0;i<n-parent;i++){char part[8];snprintf(part,sizeof part,"%s%u",i?".":"",ports[i]);strlcat(s,part,64);}}
int rh_usb_scan(RHDevice *out,int capacity,char *error,int size){pthread_once(&once,setup);if(init_error){snprintf(error,size,"%s",libusb_error_name(init_error));return -1;}libusb_device **list;ssize_t count=libusb_get_device_list(context,&list);if(count<0){snprintf(error,size,"%s",libusb_error_name((int)count));return -1;}int n=0;for(ssize_t i=0;i<count;i++){struct libusb_device_descriptor d;if(libusb_get_device_descriptor(list[i],&d))continue;if(d.bDeviceClass!=9 && !(d.idVendor==0x303a&&d.idProduct==0x1001) && !(d.idVendor==0x3563&&(d.idProduct==0x2000||d.idProduct==0x1000)))continue;if(n>=capacity){libusb_free_device_list(list,1);snprintf(error,size,"USB inventory exceeds safe capacity");return -1;}RHDevice *r=&out[n++];memset(r,0,sizeof *r);key(list[i],r->key,0);key(list[i],r->parent,1);r->vendor=d.idVendor;r->product=d.idProduct;r->kind=d.bDeviceClass;r->address=libusb_get_device_address(list[i]);}libusb_free_device_list(list,1);return n;}
typedef struct {libusb_device_handle *handle;int iface;unsigned char in,out;int packet;} USBWire;
void *rh_usb_open(const char *target,int product,int iface,char *error,int size){pthread_once(&once,setup);libusb_device **list=NULL;libusb_device *match=NULL;struct libusb_config_descriptor *cfg=NULL;USBWire *wire=NULL;int rc=init_error,found=0,claimed=0; if(rc)goto fail;ssize_t count=libusb_get_device_list(context,&list);if(count<0){rc=(int)count;goto fail;}for(ssize_t i=0;i<count;i++){char path[64];struct libusb_device_descriptor d;key(list[i],path,0);if(!strcmp(path,target)&&!libusb_get_device_descriptor(list[i],&d)&&d.idVendor==0x3563&&d.idProduct==product){match=list[i];found++;}}if(found!=1){rc=LIBUSB_ERROR_NO_DEVICE;goto fail;}rc=libusb_get_active_config_descriptor(match,&cfg);if(rc)goto fail;const struct libusb_interface_descriptor *chosen=NULL;unsigned char input=0,output=0;int packet=0,alts=0;for(int i=0;i<cfg->bNumInterfaces;i++)for(int j=0;j<cfg->interface[i].num_altsetting;j++){const struct libusb_interface_descriptor *d=&cfg->interface[i].altsetting[j];if(d->bInterfaceNumber!=iface||d->bInterfaceClass!=255)continue;int ni=0,no=0;unsigned char in=0,out=0;int mps=0;for(int k=0;k<d->bNumEndpoints;k++){const struct libusb_endpoint_descriptor *e=&d->endpoint[k];if((e->bmAttributes&3)!=2)continue;if(e->bEndpointAddress&128){in=e->bEndpointAddress;ni++;}else{out=e->bEndpointAddress;mps=e->wMaxPacketSize&0x7ff;no++;}}if(ni==1&&no==1&&mps>0){alts++;chosen=d;input=in;output=out;packet=mps;}}if(alts!=1){rc=LIBUSB_ERROR_NOT_FOUND;goto fail;}wire=calloc(1,sizeof *wire);if(!wire){rc=LIBUSB_ERROR_NO_MEM;goto fail;}wire->iface=iface;wire->in=input;wire->out=output;wire->packet=packet;rc=libusb_open(match,&wire->handle);if(rc)goto fail;rc=libusb_claim_interface(wire->handle,iface);if(rc)goto fail;claimed=1;if(chosen->bAlternateSetting){rc=libusb_set_interface_alt_setting(wire->handle,iface,chosen->bAlternateSetting);if(rc)goto fail;}libusb_free_config_descriptor(cfg);libusb_free_device_list(list,1);return wire;
fail:snprintf(error,size,"ML307 USB interface %d: %s",iface,libusb_error_name(rc));if(cfg)libusb_free_config_descriptor(cfg);if(wire){if(claimed)libusb_release_interface(wire->handle,iface);if(wire->handle)libusb_close(wire->handle);free(wire);}if(list)libusb_free_device_list(list,1);return NULL;}
int rh_usb_read(void *value,unsigned char *data,int capacity,int timeout){USBWire *w=value;int n=0;int rc=libusb_bulk_transfer(w->handle,w->in,data,capacity,&n,timeout);if(rc==LIBUSB_ERROR_TIMEOUT)return n;if(rc)return rc;return n;}
int rh_usb_write(void *value,const unsigned char *data,int size){USBWire *w=value;for(int i=0;i<size;){int count=size-i;if(count>w->packet)count=w->packet;int n=0,rc=libusb_bulk_transfer(w->handle,w->out,(unsigned char*)data+i,count,&n,5000);if(rc)return rc;if(n!=count)return LIBUSB_ERROR_IO;i+=n;}if(size%w->packet==0){int n=0,rc=libusb_bulk_transfer(w->handle,w->out,NULL,0,&n,5000);if(rc)return rc;}return size;}
void rh_usb_close(void *value){if(!value)return;USBWire *w=value;libusb_release_interface(w->handle,w->iface);libusb_close(w->handle);free(w);}
const char *rh_usb_error(int code){return libusb_error_name(code);}
int rh_serial_open(const char *path){int fd=open(path,O_RDWR|O_NOCTTY|O_NONBLOCK|O_CLOEXEC);if(fd<0)return -1;if(ioctl(fd,TIOCEXCL)<0){close(fd);return -1;}struct termios t;if(tcgetattr(fd,&t)<0){close(fd);return -1;}cfmakeraw(&t);t.c_cflag|=CLOCAL|CREAD;t.c_cflag&=~(CSTOPB|PARENB|CSIZE|CRTSCTS);t.c_cflag|=CS8;t.c_cc[VMIN]=0;t.c_cc[VTIME]=0;cfsetispeed(&t,B115200);cfsetospeed(&t,B115200);if(tcsetattr(fd,TCSANOW,&t)<0){close(fd);return -1;}return fd;}
int rh_serial_read(int fd,unsigned char *data,int capacity,int timeout){struct pollfd p={fd,POLLIN,0};int rc=poll(&p,1,timeout);if(rc==0)return 0;if(rc<0)return errno==EINTR?0:-1;if(p.revents&(POLLERR|POLLHUP|POLLNVAL))return -1;ssize_t n=read(fd,data,capacity);if(n<0&&(errno==EAGAIN||errno==EINTR))return 0;return (int)n;}
int rh_serial_write(int fd,const unsigned char *data,int size){int offset=0;while(offset<size){struct pollfd p={fd,POLLOUT,0};if(poll(&p,1,1000)<=0||p.revents&(POLLERR|POLLHUP|POLLNVAL))return -1;ssize_t n=write(fd,data+offset,size-offset);if(n<=0)return -1;offset+=(int)n;}return offset;}
int rh_spawn(const char *path,char *const argv[],int *output){int pipes[2];if(pipe(pipes))return -1;fcntl(pipes[0],F_SETFD,FD_CLOEXEC);fcntl(pipes[1],F_SETFD,FD_CLOEXEC);posix_spawn_file_actions_t actions;posix_spawn_file_actions_init(&actions);posix_spawn_file_actions_addopen(&actions,0,"/dev/null",O_RDONLY,0);posix_spawn_file_actions_adddup2(&actions,pipes[1],1);posix_spawn_file_actions_adddup2(&actions,pipes[1],2);posix_spawn_file_actions_addclose(&actions,pipes[0]);posix_spawn_file_actions_addclose(&actions,pipes[1]);posix_spawnattr_t attrs;posix_spawnattr_init(&attrs);posix_spawnattr_setflags(&attrs,POSIX_SPAWN_SETPGROUP|POSIX_SPAWN_CLOEXEC_DEFAULT);posix_spawnattr_setpgroup(&attrs,0);pid_t pid;int rc=posix_spawn(&pid,path,&actions,&attrs,argv,environ);posix_spawn_file_actions_destroy(&actions);posix_spawnattr_destroy(&attrs);close(pipes[1]);if(rc){close(pipes[0]);errno=rc;return -1;}fcntl(pipes[0],F_SETFL,O_NONBLOCK);*output=pipes[0];return pid;}
int rh_process_poll(int pid,int *code){int status;pid_t r=waitpid(pid,&status,WNOHANG);if(r==0)return 0;if(r<0)return -1;*code=WIFEXITED(status)?WEXITSTATUS(status):128+(WIFSIGNALED(status)?WTERMSIG(status):0);return 1;}
void rh_process_stop(int pid){kill(-pid,SIGTERM);usleep(100000);kill(-pid,SIGKILL);int s;while(waitpid(pid,&s,0)<0&&errno==EINTR){}}
int rh_legacy_decrypt(const unsigned char *password,int password_size,const unsigned char *cipher,int cipher_size,unsigned char *plain,int *plain_size){unsigned char key[16],iv[16];memset(iv,' ',16);int rc=CCKeyDerivationPBKDF(kCCPBKDF2,(const char*)password,password_size,(const unsigned char*)"saltysalt",9,kCCPRFHmacAlgSHA1,1003,key,16);size_t n=0;if(!rc)rc=CCCrypt(kCCDecrypt,kCCAlgorithmAES,kCCOptionPKCS7Padding,key,16,iv,cipher,cipher_size,plain,*plain_size,&n);memset_s(key,sizeof key,0,sizeof key);*plain_size=(int)n;return rc;}
